new:
	m_set_requestToAdd.emplace(dwComplex);

	// MT2009_PLUS_BOT_FRIENDS_V1 (server-patches/botfriends): a playerbot has no
	// client to show the "messenger_auth" question to - its descriptor drops
	// every packet - so a person's invitation stayed unanswered for good. The
	// bot answers it at once instead (playerbot_bot_friends.h), through the
	// same AuthToAdd a person's "Tak" or "Nie" goes through.
	if (target->GetDesc() && target->GetDesc()->IsBot())
	{
		bool Mt2009BotFriendRequest(LPCHARACTER from, LPCHARACTER bot);
		const bool accepted = Mt2009BotFriendRequest(ch, target);
		AuthToAdd(target->GetName(), ch->GetName(), !accepted);
		return;
	}

	target->ChatPacket(CHAT_TYPE_COMMAND, "messenger_auth %s", ch->GetName());
}
